inputs = {
    "DI-1": "Count each dose within 1 second of actuation",
    "DI-2": "Battery lasts at least 12 months",
    "DI-3": "Dose count visible in daylight",
}
outputs = {"DI-1": ["SRS-4", "FW-1.2"], "DI-2": ["D-110"]}
verification = {"DI-1": ["TC-12"], "DI-3": ["TC-30"]}

for di, text in inputs.items():
    gaps = []
    if not outputs.get(di):
        gaps.append("no output")
    if not verification.get(di):
        gaps.append("no verification")
    if gaps:
        print(f"{di} ({text}): {', '.join(gaps)}")
# DI-2 (Battery lasts at least 12 months): no verification
# DI-3 (Dose count visible in daylight): no output

rows = [
    {"input": "DI-07", "output": "DR-12", "out_rev": "C", "test": "T-44", "tested_rev": "B", "result": "pass"},
    {"input": "DI-08", "output": "FW-2.1", "out_rev": "2.1", "test": None, "tested_rev": None, "result": None},
    {"input": "DI-09", "output": "APP-9", "out_rev": "1.4", "test": "T-51", "tested_rev": "1.4", "result": "fail"},
]
tests = {"T-44", "T-51", "T-60"}

for r in rows:
    if not r["test"]:
        print(f"{r['input']}: no verification linked")
    elif r["tested_rev"] != r["out_rev"]:
        print(f"{r['input']}: tested rev {r['tested_rev']}, released rev {r['out_rev']}")
    elif r["result"] != "pass":
        print(f"{r['input']}: linked test {r['test']} result is {r['result']}")

linked = {r["test"] for r in rows if r["test"]}
for t in sorted(tests - linked):
    print(f"{t}: test with no requirement")
# DI-07: tested rev B, released rev C
# DI-08: no verification linked
# DI-09: linked test T-51 result is fail
# T-60: test with no requirement

import math

def success_run(confidence, reliability):
    # units to test with zero failures allowed
    return math.ceil(math.log(1 - confidence) / math.log(reliability))

for c, r in [(0.95, 0.95), (0.95, 0.90), (0.90, 0.90)]:
    print(f"C={c} R={r}: test {success_run(c, r)} units, 0 failures")
# C=0.95 R=0.95: test 59 units, 0 failures
# C=0.95 R=0.9: test 29 units, 0 failures
# C=0.9 R=0.9: test 22 units, 0 failures
